    material_type := case row_data->>'category' when 'EPI' then 'EPI' when 'EPC' then 'EPC' else 'FERRAMENTAL' end;
    material_category := case row_data->>'category' when 'EPI' then 'EPI' when 'EPC' then 'EPC' when 'ACESS' then 'ACESSORIO' when 'EQUIP' then 'EQUIPAMENTO' when 'TI' then 'TI' else 'FERRAMENTAL' end;
    unit_name := case upper(row_data->>'unit') when 'PAR' then 'PAR' when 'MT' then 'm' else 'un.' end;
    insert into public.materials (organization_id, internal_code, name, type, unit, ca_number, minimum_stock, status, contract_item_code, contract_item_number, contract_category, usage_scope, contract_source, contract_specification, ca_required, test_required, test_type, test_interval_months, report_required, art_required, notes)
