    select id into v_material_id from public.materials where organization_id = org_id and contract_item_code = 'A04-' || lpad((row_data->>'number')::text, 3, '0');
    for scenario_code, scenario_index in select * from (values ('PODA_LEVE',1),('PODA_PESADA',2),('CM_LEVE',3),('CM_PESADA',4)) as scenarios(code, idx) loop
      quantity_value := coalesce((row_data->'quantities'->>(scenario_index-1))::int, 0);
