        select id into v_scenario_id from public.contract_scenarios where organization_id = org_id and code = scenario_code;
        insert into public.contract_requirements (organization_id, scenario_id, material_id, source_annex, source_item_number, quantity, unit, usage_scope, notes)
        values (org_id, v_scenario_id, v_material_id, 'Anexo 04', (row_data->>'number')::int, quantity_value, unit_name, case row_data->>'scope' when 'IND' then 'individual' else 'coletivo' end, 'Quantidade mínima importada do Anexo 04.')
